```html
<form name="inscription" action="inscrire.php" method="post" onsubmit="return controler()">
  Nom <input type="text" name="nom"><br>
  E-mail <input type="text" name="email"><br>
  Mot de passe <input type="password" name="mdp"><br>
  <input type="submit" value="S'inscrire">
</form>

<script>
function controler() {
  var f = document.inscription;
  var motifMail = /^[A-Za-z0-9._-]+@[A-Za-z0-9.-]+\.[a-z]{2,}$/;
  if (f.nom.value === "") {
    alert("Le nom est obligatoire");
    f.nom.focus();
    return false;
  }
  if (!motifMail.test(f.email.value)) {
    alert("Adresse e-mail invalide");
    f.email.focus();
    return false;
  }
  if (f.mdp.value.length < 8) {
    alert("Le mot de passe doit avoir au moins 8 caractères");
    return false;
  }
  return true;     // l'envoi est autorisé
}
</script>
```

Le gestionnaire `onsubmit="return controler()"` annule l'envoi quand la fonction renvoie `false`.

```javascript
function ttc(ht, taux) {
  return Math.round(ht * (1 + taux) * 100) / 100;
}
ttc(1000, 0.18);   // 1180
```

```javascript
function moyenne(t) {
  var somme = 0;
  for (var i = 0; i < t.length; i++) { somme += t[i]; }
  return t.length ? somme / t.length : 0;
}
moyenne([12, 15, 9]);   // 12
```

```javascript
function max(t) {
  var m = t[0];
  for (var i = 1; i < t.length; i++) { if (t[i] > m) { m = t[i]; } }
  return m;
}
max([3, 9, 2]);   // 9
```
